                    if 0<=yy<h and 0<=xx<w and grid[yy][xx] and (yy,xx) not in seen:
                        seen.add((yy,xx)); todo.append((yy,xx))
            colors={grid[y][x] for y,x in cells}
            bounds={k:(min(y for y,x in cells if grid[y][x]==k),max(y for y,x in cells if grid[y][x]==k),min(x for y,x in cells if grid[y][x]==k),max(x for y,x in cells if grid[y][x]==k)) for k in colors}
            ordered=sorted(colors,key=lambda k:(-((bounds[k][1]-bounds[k][0]+1)*(bounds[k][3]-bounds[k][2]+1)),k))
            remap=dict(zip(ordered,reversed(ordered)))
            for y,x in cells: out[y][x]=remap[grid[y][x]]
    return out

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; seen=set()
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); cells=[]
            while todo:
                y,x=todo.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx] and (yy,xx) not in seen:
                        seen.add((yy,xx)); todo.append((yy,xx))
            colors={grid[y][x] for y,x in cells}
            bounds={k:(min(y for y,x in cells if grid[y][x]==k),max(y for y,x in cells if grid[y][x]==k),min(x for y,x in cells if grid[y][x]==k),max(x for y,x in cells if grid[y][x]==k)) for k in colors}
            ordered=sorted(colors,key=lambda k:(-((bounds[k][1]-bounds[k][0]+1)*(bounds[k][3]-bounds[k][2]+1)),k))
            remap=dict(zip(ordered,reversed(ordered)))
            for y,x in cells: out[y][x]=remap[grid[y][x]]
    return out
